<?php
require __DIR__.'/ui.php';role(['admin','gerente']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$p->prepare("INSERT INTO subscriptions(customer_id,product_id,description,frequency,next_date,amount,status,notes)VALUES(?,?,?,?,?,?,'Ativa',?)")->execute([$_POST['customer_id'],$_POST['product_id']?:null,$_POST['description'],$_POST['frequency'],$_POST['next_date'],$_POST['amount'],$_POST['notes']]);go('subscriptions.php');}$customers=$p->query("SELECT id,name FROM customers ORDER BY name")->fetchAll();$products=$p->query("SELECT id,name FROM products ORDER BY name")->fetchAll();$rows=$p->query("SELECT s.*,c.name customer,p.name product FROM subscriptions s JOIN customers c ON c.id=s.customer_id LEFT JOIN products p ON p.id=s.product_id ORDER BY s.next_date")->fetchAll();page_head('Assinaturas recorrentes');?>
<div class="grid g2"><div class="card"><h2>Nova assinatura</h2><form method="post"><?=csrf_field()?><label>Cliente</label><select name="customer_id"><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select><label>Produto</label><select name="product_id"><option value="">Personalizado</option><?php foreach($products as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select><label>Descrição</label><input name="description"><div class="grid g3"><div><label>Frequência</label><select name="frequency"><option>Semanal</option><option>Quinzenal</option><option>Mensal</option></select></div><div><label>Próxima data</label><input type="date" name="next_date"></div><div><label>Valor</label><input type="number" step=".01" name="amount"></div></div><label>Notas</label><textarea name="notes"></textarea><button class="primary">Salvar</button></form></div><div class="card"><h2>Próximas recorrências</h2><?php foreach($rows as $r):?><p><b><?=e($r['next_date'])?></b> — <?=e($r['customer'])?> • <?=e($r['product']?:$r['description'])?> • <?=money($r['amount'])?></p><?php endforeach;?></div></div><?php page_foot();?>